   value = tja1100ReadPhyReg(interface, TJA1100_CONFIG1);
   value |= TJA1100_CONFIG1_AUTO_OP;
   tja1100WritePhyReg(interface, TJA1100_CONFIG1, value);


   interface->phyEvent = TRUE;

   osSetEvent(&netEvent);


   return NO_ERROR;
}

