inline bool ParameterSerializer<ParameterToken_t>::read_content_from_cdr_message(
        ParameterToken_t& parameter,
        fastrtps::rtps::CDRMessage_t* cdr_message,
        const uint16_t parameter_length)
{

    parameter.length = parameter_length;
    uint32_t pos_ref = cdr_message->pos;
    bool valid =  fastrtps::rtps::CDRMessage::readDataHolder(cdr_message, parameter.token);
    uint32_t length_diff = cdr_message->pos - pos_ref;
    valid &= (parameter_length == length_diff);
    return valid;
}

inline bool ParameterSerializer<ParameterToken_t>::read_content_from_cdr_message(
        ParameterToken_t& parameter,
        fastrtps::rtps::CDRMessage_t* cdr_message,
        const uint16_t parameter_length)
{

    parameter.length = parameter_length;
    uint32_t pos_ref = cdr_message->pos;
    bool valid =  fastrtps::rtps::CDRMessage::readDataHolder(cdr_message, parameter.token, parameter_length);
    uint32_t length_diff = cdr_message->pos - pos_ref;
    valid &= (parameter_length == length_diff);
    return valid;
}

int init_result(RESULT & result, void*& data) {
	FILE* f;
	std::string line;
	int retval, n;
	DATA* dp = new DATA;

	OUTPUT_FILE_INFO fi;

	log_messages.printf(MSG_DEBUG, "Start\n");

	retval = get_output_file_path(result, fi.path);
	if (retval) {
		log_messages.printf(MSG_CRITICAL, "Unable to open file\n");
		return -1;
	}

	f = fopen(fi.path.c_str(), "r");

	if (f == NULL) {
		log_messages.printf(MSG_CRITICAL,
				"Open error: %s\n errno: %s Waiting...\n", fi.path.c_str(),
				errno);
		usleep(1000);
		log_messages.printf(MSG_CRITICAL, "Try again...\n");
		f = fopen(fi.path.c_str(), "r");
		if (f == NULL) {
			return -1;
		}
	}
	log_messages.printf(MSG_DEBUG, "Check result\n");

	char buff[256];
	n = fscanf(f, "%s", buff);
	char * pch;
	pch = strtok(buff, " ,");
	if (pch != NULL) {
		dp->receptor = pch;
	} else {
		log_messages.printf(MSG_CRITICAL, "Seek receptor failed\n");
		return -1;
	}
	pch = strtok(NULL, ",");
	if (pch != NULL) {
		dp->ligand = pch;
	} else {
		log_messages.printf(MSG_CRITICAL, "Seek ligand failed\n");
		return -1;
	}
	pch = strtok(NULL, ",");
	if (pch != NULL) {
		dp->seed = strtod(pch, NULL);
	} else {
		log_messages.printf(MSG_CRITICAL, "Seek seed failed\n");
		return -1;
	}
	pch = strtok(NULL, ",");
	if (pch != NULL) {
		dp->score = atof(pch);
