	}

	MavlinkShell *shell = _mavlink.get_shell();

	if (shell) {

		if (serial_control_mavlink.count > 0 && serial_control_mavlink.count <= sizeof(serial_control_mavlink.data)) {
			shell->setTargetID(msg->sysid, msg->compid);
			shell->write(serial_control_mavlink.data, serial_control_mavlink.count);
		}


		if ((serial_control_mavlink.flags & SERIAL_CONTROL_FLAG_RESPOND) == 0) {
			_mavlink.close_shell();
		}
	}
}

bool MavlinkLogHandler::log_entry_from_id(uint16_t log_id, LogEntry *entry)
{
	DIR *dp = opendir(kLogDir);

	if (!dp) {
		PX4_INFO("No logs available");
		return false;
	}

	FILE *fp = fopen(kLogListFilePath, "r");

	if (!fp) {
		PX4_DEBUG("Failed to open %s", kLogListFilePath);
		closedir(dp);
		return false;
	}

	bool found_entry = false;
	uint16_t current_id = 0;
	char line[PX4_MAX_FILEPATH];

	while (fgets(line, sizeof(line), fp)) {

		if (current_id != log_id) {
			current_id++;
			continue;
		}

		if (sscanf(line, "%" PRIu32 " %" PRIu32 " %s", &(entry->time_utc), &(entry->size_bytes), entry->filepath) != 3) {
			PX4_DEBUG("sscanf failed");
			continue;
		}

		entry->id = log_id;
		found_entry = true;
		break;
	}

	fclose(fp);
	closedir(dp);

	return found_entry;
}

