void COptionsWindow::OnSetPassword()
{
	auto pBoxEx = m_pBox.objectCast<CSandBoxPlus>();
	bool bNew = !QFile::exists(pBoxEx->GetBoxImagePath());
	CBoxImageWindow window(bNew ? CBoxImageWindow::eNew : CBoxImageWindow::eChange, this);
	if (bNew) window.SetImageSize(m_ImageSize);
	if (theGUI->SafeExec(&window) == 1) {
		m_Password = window.GetPassword();
		if (bNew) {
			m_ImageSize = window.GetImageSize();
			OnGeneralChanged();
		}
		else {

			QStringList Arguments;
			Arguments.append("type=image");
			Arguments.append("image=" + pBoxEx->GetBoxImagePath());
			Arguments.append("key=" + m_Password);
			Arguments.append("new_key=" + window.GetNewPassword());

			if (RunImBox(Arguments))
				QMessageBox::information(this, "Sandboxie-Plus", tr("Image Password Changed"));
		}
	}
}

void COptionsWindow::OnSetPassword()
{
	auto pBoxEx = m_pBox.objectCast<CSandBoxPlus>();
	bool bNew = !QFile::exists(pBoxEx->GetBoxImagePath());
	CBoxImageWindow window(bNew ? CBoxImageWindow::eNew : CBoxImageWindow::eChange, this);
	if (bNew) window.SetImageSize(m_ImageSize);
	if (theGUI->SafeExec(&window) == 1) {
		m_Password = window.GetPassword();
		if (bNew) {
			m_ImageSize = window.GetImageSize();
			OnGeneralChanged();
		}
		else {

			QString NewPassword = window.GetNewPassword();
			QByteArray Buffer;
			Buffer.resize((NewPassword.size() + 1) * sizeof(wchar_t));
			memcpy(Buffer.data(), NewPassword.utf16(), Buffer.size());
			SB_STATUS Status = theAPI->ExecImDisk(pBoxEx->GetBoxImagePath(), m_Password, "new_key", true, &Buffer, SECTION_PARAM_ID_KEY);
			if(Status)
				QMessageBox::information(this, "Sandboxie-Plus", tr("Image Password Changed"));
			else
				QMessageBox::critical(this, "Sandboxie-Plus", tr("Failed to Change Password"));
		}
	}
}

void sdb_edit(procinfo *pi)
{
  char * filename = omStrDup("/tmp/sd000000");
  sprintf(filename+7,"%d",getpid());
  FILE *fp=fopen(filename,"w");
  if (fp==NULL)
  {
    Print("cannot open %s\n",filename);
    omFree(filename);
    return;
  }
  if (pi->language!= LANG_SINGULAR)
  {
    Print("cannot edit type %d\n",pi->language);
    fclose(fp);
    fp=NULL;
  }
  else
  {
    const char *editor=getenv("EDITOR");
    if (editor==NULL)
      editor=getenv("VISUAL");
    if (editor==NULL)
      editor="vi";
    editor=omStrDup(editor);

    if (pi->data.s.body==NULL)
    {
      iiGetLibProcBuffer(pi);
      if (pi->data.s.body==NULL)
      {
        PrintS("cannot get the procedure body\n");
        fclose(fp);
        si_unlink(filename);
        omFree(filename);
        return;
      }
    }

    fwrite(pi->data.s.body,1,strlen(pi->data.s.body),fp);
    fclose(fp);

    int pid=fork();
    if (pid!=0)
    {
      si_wait(&pid);
    }
    else if(pid==0)
    {
      if (strchr(editor,' ')==NULL)
      {
        execlp(editor,editor,filename,NULL);
        Print("cannot exec %s\n",editor);
      }
      else
      {
        char *p=(char *)omAlloc(strlen(editor)+strlen(filename)+2);
        sprintf(p,"%s %s",editor,filename);
        system(p);
      }
      exit(0);
    }
    else
    {
      PrintS("cannot fork\n");
    }

    fp=fopen(filename,"r");
    if (fp==NULL)
    {
      Print("cannot read from %s\n",filename);
    }
    else
    {
      fseek(fp,0L,SEEK_END);
      long len=ftell(fp);
      fseek(fp,0L,SEEK_SET);

      omFree((ADDRESS)pi->data.s.body);
      pi->data.s.body=(char *)omAlloc((int)len+1);
      myfread( pi->data.s.body, len, 1, fp);
      pi->data.s.body[len]='\0';
      fclose(fp);
    }
  }
  si_unlink(filename);
  omFree(filename);
}

