typename BasicWriter<Char>::CharPtr
  BasicWriter<Char>::prepare_int_buffer(
    unsigned num_digits, const Spec &spec,
    const char *prefix, unsigned prefix_size) {
  unsigned width = spec.width();
  Alignment align = spec.align();
  Char fill = internal::CharTraits<Char>::cast(spec.fill());
  if (spec.precision() > static_cast<int>(num_digits)) {


    if (prefix_size > 0 && prefix[prefix_size - 1] == '0')
      --prefix_size;
    unsigned number_size =
        prefix_size + internal::to_unsigned(spec.precision());
    AlignSpec subspec(number_size, '0', ALIGN_NUMERIC);
    if (number_size >= width)
      return prepare_int_buffer(num_digits, subspec, prefix, prefix_size);
    buffer_.reserve(width);
    unsigned fill_size = width - number_size;
    if (align != ALIGN_LEFT) {
      CharPtr p = grow_buffer(fill_size);
      std::uninitialized_fill(p, p + fill_size, fill);
    }
    CharPtr result = prepare_int_buffer(
        num_digits, subspec, prefix, prefix_size);
    if (align == ALIGN_LEFT) {
      CharPtr p = grow_buffer(fill_size);
      std::uninitialized_fill(p, p + fill_size, fill);
    }
    return result;
  }
  unsigned size = prefix_size + num_digits;
  if (width <= size) {
    CharPtr p = grow_buffer(size);
    std::uninitialized_copy(prefix, prefix + prefix_size, p);
    return p + size - 1;
  }
  CharPtr p = grow_buffer(width);
  CharPtr end = p + width;
  if (align == ALIGN_LEFT) {
    std::uninitialized_copy(prefix, prefix + prefix_size, p);
    p += size;
    std::uninitialized_fill(p, end, fill);
  } else if (align == ALIGN_CENTER) {
    p = fill_padding(p, width, size, fill);
    std::uninitialized_copy(prefix, prefix + prefix_size, p);
    p += size;
  } else {
    if (align == ALIGN_NUMERIC) {
      if (prefix_size != 0) {
        p = std::uninitialized_copy(prefix, prefix + prefix_size, p);
        size -= prefix_size;
      }
    } else {
      std::uninitialized_copy(prefix, prefix + prefix_size, end - size);
    }
    std::uninitialized_fill(p, end - size, fill);
    p = end;
  }
  return p - 1;
}

typename BasicWriter<Char>::CharPtr
  BasicWriter<Char>::prepare_int_buffer(
    unsigned num_digits, const Spec &spec,
    const char *prefix, unsigned prefix_size) {
  unsigned width = spec.width();
  Alignment align = spec.align();
  Char fill = internal::CharTraits<Char>::cast(spec.fill());
  if (spec.precision() > static_cast<int>(num_digits)) {


    if (prefix_size > 0 && prefix[prefix_size - 1] == '0')
      --prefix_size;
    unsigned number_size =
        prefix_size + internal::to_unsigned(spec.precision());
    AlignSpec subspec(number_size, '0', ALIGN_NUMERIC);
    if (number_size >= width)
      return prepare_int_buffer(num_digits, subspec, prefix, prefix_size);
    buffer_.reserve(width);
    unsigned fill_size = width - number_size;
    if (align != ALIGN_LEFT) {
      CharPtr p = grow_buffer(fill_size);
      std::uninitialized_fill(p, p + fill_size, fill);
    }
    std::ptrdiff_t offset = get(prepare_int_buffer(
        num_digits, subspec, prefix, prefix_size)) - &buffer_[0];
    if (align == ALIGN_LEFT) {
      CharPtr p = grow_buffer(fill_size);
      std::uninitialized_fill(p, p + fill_size, fill);
    }
    return internal::make_ptr(&buffer_[0], buffer_.size()) + offset;
  }
  unsigned size = prefix_size + num_digits;
  if (width <= size) {
    CharPtr p = grow_buffer(size);
    std::uninitialized_copy(prefix, prefix + prefix_size, p);
    return p + size - 1;
  }
  CharPtr p = grow_buffer(width);
  CharPtr end = p + width;
  if (align == ALIGN_LEFT) {
    std::uninitialized_copy(prefix, prefix + prefix_size, p);
    p += size;
    std::uninitialized_fill(p, end, fill);
  } else if (align == ALIGN_CENTER) {
    p = fill_padding(p, width, size, fill);
    std::uninitialized_copy(prefix, prefix + prefix_size, p);
    p += size;
  } else {
    if (align == ALIGN_NUMERIC) {
      if (prefix_size != 0) {
        p = std::uninitialized_copy(prefix, prefix + prefix_size, p);
        size -= prefix_size;
      }
    } else {
      std::uninitialized_copy(prefix, prefix + prefix_size, end - size);
    }
    std::uninitialized_fill(p, end - size, fill);
    p = end;
  }
  return p - 1;
}

SerializeStatus FilePacket ::fromSerialBuffer(SerialBuffer& serialBuffer) {
    SerializeStatus status;
    status = this->m_header.fromSerialBuffer(serialBuffer);
    if (status != FW_SERIALIZE_OK) {
        return status;
    }

    switch (this->m_header.m_type) {
        case T_START:
            status = this->m_startPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_DATA:
            status = this->m_dataPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_END:
            status = this->m_endPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_CANCEL:
            status = this->m_cancelPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_NONE:
            status = FW_DESERIALIZE_TYPE_MISMATCH;
            break;
        default:
            FW_ASSERT(0, status);
            break;
    }
    return status;
}

SerializeStatus FilePacket ::fromSerialBuffer(SerialBuffer& serialBuffer) {
    SerializeStatus status;
    status = this->m_header.fromSerialBuffer(serialBuffer);
    if (status != FW_SERIALIZE_OK) {
        return status;
    }

    switch (this->m_header.m_type) {
        case T_START:
            status = this->m_startPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_DATA:
            status = this->m_dataPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_END:
            status = this->m_endPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_CANCEL:
            status = this->m_cancelPacket.fromSerialBuffer(serialBuffer);
            break;
        case T_NONE:
            status = FW_DESERIALIZE_TYPE_MISMATCH;
            break;
        default:
            status = FW_DESERIALIZE_INVALID_DATA;
            break;
    }
    return status;
}

void SpacePacketDeframer ::dataIn_handler(FwIndexType portNum, Fw::Buffer& data, const ComCfg::FrameContext& context) {















    FW_ASSERT(data.getSize() > SpacePacketHeader::SERIALIZED_SIZE, static_cast<FwAssertArgType>(data.getSize()));

    SpacePacketHeader header;
    Fw::SerializeStatus status = data.getDeserializer().deserializeTo(header);
    FW_ASSERT(status == Fw::FW_SERIALIZE_OK, status);



    U16 pkt_length = static_cast<U16>(header.get_packetDataLength() + 1);
    if (pkt_length > data.getSize() - SpacePacketHeader::SERIALIZED_SIZE) {
        FwSizeType maxDataAvailable = data.getSize() - SpacePacketHeader::SERIALIZED_SIZE;
        this->log_WARNING_HI_InvalidLength(pkt_length, maxDataAvailable);
        if (this->isConnected_errorNotify_OutputPort(0)) {
            this->errorNotify_out(0, Svc::Ccsds::FrameError::SP_INVALID_LENGTH);
        }
        this->dataReturnOut_out(0, data, context);  
        return;
    }

    U16 apidValue = header.get_packetIdentification() & SpacePacketSubfields::ApidMask;
    ComCfg::Apid::T apid = static_cast<ComCfg::Apid::T>(apidValue);
    ComCfg::FrameContext contextCopy = context;
    contextCopy.set_apid(apid);


    U16 receivedSequenceCount = header.get_packetSequenceControl() & SpacePacketSubfields::SeqCountMask;
    (void)this->validateApidSeqCount_out(0, apid, receivedSequenceCount);
    contextCopy.set_sequenceCount(receivedSequenceCount);


    data.setData(data.getData() + SpacePacketHeader::SERIALIZED_SIZE);
    data.setSize(pkt_length);

    this->dataOut_out(0, data, contextCopy);
}

void SpacePacketDeframer ::dataIn_handler(FwIndexType portNum, Fw::Buffer& data, const ComCfg::FrameContext& context) {
















    if (data.getSize() <= SpacePacketHeader::SERIALIZED_SIZE) {
        this->log_WARNING_HI_InvalidPacket();
        if (this->isConnected_errorNotify_OutputPort(0)) {
            this->errorNotify_out(0, Svc::Ccsds::FrameError::SP_INVALID_PACKET);
        }
        this->dataReturnOut_out(0, data, context);  
        return;
    }

    SpacePacketHeader header;
    Fw::SerializeStatus status = data.getDeserializer().deserializeTo(header);

    FW_ASSERT(status == Fw::FW_SERIALIZE_OK, status);



    U16 pkt_length = static_cast<U16>(header.get_packetDataLength() + 1);
    if (pkt_length > data.getSize() - SpacePacketHeader::SERIALIZED_SIZE) {
        FwSizeType maxDataAvailable = data.getSize() - SpacePacketHeader::SERIALIZED_SIZE;
        this->log_WARNING_HI_InvalidLength(pkt_length, maxDataAvailable);
        if (this->isConnected_errorNotify_OutputPort(0)) {
            this->errorNotify_out(0, Svc::Ccsds::FrameError::SP_INVALID_LENGTH);
        }
        this->dataReturnOut_out(0, data, context);  
        return;
    }

    U16 apidValue = header.get_packetIdentification() & SpacePacketSubfields::ApidMask;
    ComCfg::Apid::T apid = static_cast<ComCfg::Apid::T>(apidValue);
    ComCfg::FrameContext contextCopy = context;
    contextCopy.set_apid(apid);


    U16 receivedSequenceCount = header.get_packetSequenceControl() & SpacePacketSubfields::SeqCountMask;
    (void)this->validateApidSeqCount_out(0, apid, receivedSequenceCount);
    contextCopy.set_sequenceCount(receivedSequenceCount);


    data.setData(data.getData() + SpacePacketHeader::SERIALIZED_SIZE);
    data.setSize(pkt_length);

    this->dataOut_out(0, data, contextCopy);
}

void TcDeframer ::dataIn_handler(FwIndexType portNum, Fw::Buffer& data, const ComCfg::FrameContext& context) {


















    FW_ASSERT(data.getSize() > TCHeader::SERIALIZED_SIZE + TCTrailer::SERIALIZED_SIZE,
              static_cast<FwAssertArgType>(data.getSize()));

    TCHeader header;
    Fw::SerializeStatus status = data.getDeserializer().deserializeTo(header);
    FW_ASSERT(status == Fw::FW_SERIALIZE_OK, status);

    U16 total_frame_length = static_cast<U16>((header.get_vcIdAndLength() & TCSubfields::FrameLengthMask) + 1);
    U8 vc_id = static_cast<U8>((header.get_vcIdAndLength() & TCSubfields::VcIdMask) >> TCSubfields::VcIdOffset);
    U16 spacecraft_id = header.get_flagsAndScId() & TCSubfields::SpacecraftIdMask;

    if (spacecraft_id != this->m_spacecraftId) {
        this->log_WARNING_LO_InvalidSpacecraftId(spacecraft_id, this->m_spacecraftId);
        this->errorNotifyHelper(Ccsds::FrameError::TC_INVALID_SCID);
        this->dataReturnOut_out(0, data, context);  
        return;
    }


    if ((data.getSize() < static_cast<Fw::Buffer::SizeType>(total_frame_length)) or
        (total_frame_length < TCHeader::SERIALIZED_SIZE + TCTrailer::SERIALIZED_SIZE)) {
        FwSizeType maxDataAvailable = static_cast<FwSizeType>(data.getSize());
        this->log_WARNING_HI_InvalidFrameLength(total_frame_length, maxDataAvailable);
        this->errorNotifyHelper(Ccsds::FrameError::TC_INVALID_LENGTH);
        this->dataReturnOut_out(0, data, context);  
        return;
    }
    if (not this->m_acceptAllVcid && vc_id != this->m_vcId) {
        this->log_ACTIVITY_LO_InvalidVcId(vc_id, this->m_vcId);
        this->errorNotifyHelper(Ccsds::FrameError::TC_INVALID_VCID);
        this->dataReturnOut_out(0, data, context);  
        return;
    }







    U16 computed_crc = Ccsds::Utils::CRC16::compute(data.getData(), total_frame_length - TCTrailer::SERIALIZED_SIZE);
    TCTrailer trailer;
    auto deserializer = data.getDeserializer();
    deserializer.moveDeserToOffset(total_frame_length - TCTrailer::SERIALIZED_SIZE);
    status = deserializer.deserializeTo(trailer);
    FW_ASSERT(status == Fw::FW_SERIALIZE_OK, status);

    U16 transmitted_crc = trailer.get_fecf();
    if (transmitted_crc != computed_crc) {
        this->log_WARNING_HI_InvalidCrc(computed_crc, transmitted_crc);
        this->errorNotifyHelper(Ccsds::FrameError::TC_INVALID_CRC);
        this->dataReturnOut_out(0, data, context);  
        return;
    }


    data.setData(data.getData() + TCHeader::SERIALIZED_SIZE);

    data.setSize(total_frame_length - TCHeader::SERIALIZED_SIZE - TCTrailer::SERIALIZED_SIZE);

    this->dataOut_out(0, data, context);
}

