			vty_out(vty, "	Link data: %pI4\n", &top->link_data);
		} else {
			zlog_debug("  Extended Link TLV: Length %u", ntohs(top->header.length));
			zlog_debug("    Link Type: 0x%x", top->link_type);
			zlog_debug("    Link ID: %pI4", &top->link_id);
			zlog_debug("    Link data: %pI4", &top->link_data);
		}
	} else {
		json_object_string_addf(json, "linkType", "0x%x",
					top->link_type);
		json_object_string_addf(json, "linkID", "%pI4", &top->link_id);
		json_object_string_addf(json, "linkData", "%pI4",
					&top->link_data);
		jadj = json_object_new_array();
		json_object_object_add(json, "adjacencySID", jadj);
	}


	length -= EXT_TLV_LINK_SIZE;
	tlvh = (struct tlv_header *)((char *)(ext) + TLV_HDR_SIZE
				     + EXT_TLV_LINK_SIZE);
	for (; sum < length && tlvh; tlvh = TLV_HDR_NEXT(tlvh)) {
		switch (ntohs(tlvh->type)) {
		case EXT_SUBTLV_ADJ_SID:
			if (json) {
				obj = json_object_new_object();
				json_object_array_add(jadj, obj);
			} else
				obj = NULL;
			sum += show_vty_ext_link_adj_sid(vty, tlvh, obj);
			break;
		case EXT_SUBTLV_LAN_ADJ_SID:
			if (json) {
				obj = json_object_new_object();
				json_object_array_add(jadj, obj);
			} else
				obj = NULL;
			sum += show_vty_ext_link_lan_adj_sid(vty, tlvh, obj);
			break;
		case EXT_SUBTLV_RMT_ITF_ADDR:
			sum += show_vty_ext_link_rmt_itf_addr(vty, tlvh, json);
			break;
		default:
			sum += show_vty_unknown_tlv(vty, tlvh, length - sum,
						    json);
			break;
		}
	}

	return sum + sizeof(struct ext_tlv_link);
}

static uint16_t show_vty_unknown_tlv(struct vty *vty, struct tlv_header *tlvh,
				     size_t buf_size, json_object *json)
{
	json_object *obj;

	if (TLV_SIZE(tlvh) > buf_size) {
		vty_out(vty, "    TLV size %d exceeds buffer size. Abort!",
			TLV_SIZE(tlvh));
		return buf_size;
	}
	if (!json)
		vty_out(vty, "    Unknown TLV: [type(0x%x), length(0x%x)]\n",
			ntohs(tlvh->type), ntohs(tlvh->length));
	else {
		obj = json_object_new_object();
		json_object_string_addf(obj, "type", "0x%x",
					ntohs(tlvh->type));
		json_object_string_addf(obj, "length", "0x%x",
					ntohs(tlvh->length));
		json_object_object_add(json, "unknownTLV", obj);
	}

	return TLV_SIZE(tlvh);
}

static uint16_t show_vty_unknown_tlv(struct vty *vty, struct tlv_header *tlvh,
				     size_t buf_size, json_object *json)
{
	json_object *obj;


	if (TLV_SIZE(tlvh) > buf_size) {
		if (vty != NULL)
			vty_out(vty, "    TLV size %d exceeds buffer size. Abort!", TLV_SIZE(tlvh));
		else
			zlog_debug("    TLV size %d exceeds buffer size. Abort!", TLV_SIZE(tlvh));
	}
	if (!json)
		if (vty != NULL) {
			vty_out(vty, "    Unknown TLV: [type(0x%x), length(0x%x)]\n",
				ntohs(tlvh->type), ntohs(tlvh->length));
		} else {
			zlog_debug("    Unknown TLV: [type(0x%x), length(0x%x)]",
				   ntohs(tlvh->type), ntohs(tlvh->length));
		}
	else {
		obj = json_object_new_object();
		json_object_string_addf(obj, "type", "0x%x",
					ntohs(tlvh->type));
		json_object_string_addf(obj, "length", "0x%x",
					ntohs(tlvh->length));
		json_object_object_add(json, "unknownTLV", obj);
	}

	return TLV_SIZE(tlvh);
}

static int process_type2_route(struct peer *peer, afi_t afi, safi_t safi,
			       struct attr *attr, uint8_t *pfx, int psize,
			       uint32_t addpath_id)
{
	struct prefix_rd prd;
	struct prefix_evpn p = {};
	uint8_t ipaddr_len;
	uint8_t macaddr_len;

	mpls_label_t label[BGP_MAX_LABELS] = {};
	uint8_t num_labels = 0;
	uint32_t eth_tag;
	int ret = 0;







	if (psize != 33 && psize != 37 && psize != 49 && psize != 36
	    && psize != 40 && psize != 52) {
		flog_err(EC_BGP_EVPN_ROUTE_INVALID,
			 "%u:%s - Rx EVPN Type-2 NLRI with invalid length %d",
			 peer->bgp->vrf_id, peer->host, psize);
		return -1;
	}

	struct stream *pkt = stream_new(psize);
	stream_put(pkt, pfx, psize);


	prd.family = AF_UNSPEC;
	prd.prefixlen = 64;

	STREAM_GET(&prd.val, pkt, 8);


	p.family = AF_EVPN;
	p.prefixlen = EVPN_ROUTE_PREFIXLEN;
	p.prefix.route_type = BGP_EVPN_MAC_IP_ROUTE;


	if (attr) {
		STREAM_GET(&attr->esi, pkt, sizeof(esi_t));

		if (bgp_evpn_is_esi_local_and_non_bypass(&attr->esi))
			SET_FLAG(attr->es_flags, ATTR_ES_IS_LOCAL);
		else
			UNSET_FLAG(attr->es_flags, ATTR_ES_IS_LOCAL);
	} else {
		STREAM_FORWARD_GETP(pkt, sizeof(esi_t));
	}


	STREAM_GET(&eth_tag, pkt, 4);
	p.prefix.macip_addr.eth_tag = ntohl(eth_tag);


	STREAM_GETC(pkt, macaddr_len);


	if (macaddr_len == (ETH_ALEN * 8)) {
		STREAM_GET(&p.prefix.macip_addr.mac.octet, pkt, ETH_ALEN);
	} else {
		flog_err(
			EC_BGP_EVPN_ROUTE_INVALID,
			"%u:%s - Rx EVPN Type-2 NLRI with unsupported MAC address length %d",
			peer->bgp->vrf_id, peer->host, macaddr_len);
		goto fail;
	}



	STREAM_GETC(pkt, ipaddr_len);

	if (ipaddr_len != 0 && ipaddr_len != IPV4_MAX_BITLEN
	    && ipaddr_len != IPV6_MAX_BITLEN) {
		flog_err(
			EC_BGP_EVPN_ROUTE_INVALID,
			"%u:%s - Rx EVPN Type-2 NLRI with unsupported IP address length %d",
			peer->bgp->vrf_id, peer->host, ipaddr_len);
		goto fail;
	}

	if (ipaddr_len) {
		ipaddr_len /= 8; 
		p.prefix.macip_addr.ip.ipa_type = (ipaddr_len == IPV4_MAX_BYTELEN)
					       ? IPADDR_V4
					       : IPADDR_V6;
		STREAM_GET(&p.prefix.macip_addr.ip.ip.addr, pkt, ipaddr_len);
	}


	STREAM_GET(&label[0], pkt, BGP_LABEL_BYTES);
	num_labels++;


	if (STREAM_READABLE(pkt)) {
		num_labels++;
		STREAM_GET(&label[1], pkt, BGP_LABEL_BYTES);
	}


	if (attr)
		bgp_update(peer, (struct prefix *)&p, addpath_id, attr, afi,
			   safi, ZEBRA_ROUTE_BGP, BGP_ROUTE_NORMAL, &prd,
			   &label[0], num_labels, 0, NULL);
	else
		bgp_withdraw(peer, (struct prefix *)&p, addpath_id, afi, safi,
			     ZEBRA_ROUTE_BGP, BGP_ROUTE_NORMAL, &prd, &label[0],
			     num_labels);
	goto done;

fail:
stream_failure:
	flog_err(EC_BGP_EVPN_ROUTE_INVALID,
		 "%u:%s - Rx EVPN Type-2 NLRI - corrupt, discarding",
		 peer->bgp->vrf_id, peer->host);
	ret = -1;
done:
	stream_free(pkt);
	return ret;
}

