		       bpi->extra->vnc->vnc.import.rd.val + 2, ETH_ALEN);

		(void)rfapiEcommunityGetLNI(bgp_attr_get_ecommunity(bpi->attr),
					    &vo->v.l2addr.logical_net_id);
