static bool identifyCallsites(
    Function *F,
    llvh::DenseSet<CallInst *> &callSites) {
  for (auto *CU : F->getUsers()) {
    if (auto *CI = llvh::dyn_cast<CallInst>(CU)) {
      if (!isDirectCallee(F, CI))
        return false;
      callSites.insert(CI);
    } else if (auto *CFI = llvh::dyn_cast<CreateFunctionInst>(CU)) {
      for (auto *CL : CFI->getUsers()) {
        auto *CI = llvh::dyn_cast<CallInst>(CL);
        if (!CI)
          return false;

        if (!isDirectCallee(CFI, CI))
          return false;
        callSites.insert(CI);
      }
    } else {
      return false;
    }
  }
  return true;
}

static bool identifyCallsites(
    Function *F,
    llvh::DenseSet<CallInst *> &callSites) {



  if (!F->isStrictMode()) {
    return false;
  }

  for (auto *CU : F->getUsers()) {
    if (auto *CI = llvh::dyn_cast<CallInst>(CU)) {
      if (!isDirectCallee(F, CI))
        return false;
      callSites.insert(CI);
    } else if (auto *CFI = llvh::dyn_cast<CreateFunctionInst>(CU)) {
      for (auto *CL : CFI->getUsers()) {
        auto *CI = llvh::dyn_cast<CallInst>(CL);
        if (!CI)
          return false;

        if (!isDirectCallee(CFI, CI))
          return false;
        callSites.insert(CI);
      }
    } else {
      return false;
    }
  }
  return true;
}

Resource* ResourceHost::getResource(std::string uri) {
	if (uri.length() > 255 || uri.empty())
		return NULL;

	std::string path = baseDiskPath + uri;
	Resource* res = NULL;


	struct stat sb;
	if (stat(path.c_str(), &sb) == -1)
		return NULL; 


	if (sb.st_mode & S_IFDIR) { 

		res = readDirectory(path, sb);
	} else if (sb.st_mode & S_IFREG) { 

		res = readFile(path, sb);
	} else { 
		return NULL;
	}

	return res;
}

Resource* ResourceHost::getResource(std::string uri) {
	if (uri.length() > 255 || uri.empty())
		return NULL;

	if (uri.find("../") != std::string::npos)
		return NULL;

	std::string path = baseDiskPath + uri;
	Resource* res = NULL;


	struct stat sb;
	if (stat(path.c_str(), &sb) == -1)
		return NULL; 


	if (sb.st_mode & S_IFDIR) { 

		res = readDirectory(path, sb);
	} else if (sb.st_mode & S_IFREG) { 

		res = readFile(path, sb);
	} else { 
		return NULL;
	}

	return res;
}

uint64_t
vi_pci_read(UNUSED int vcpu, struct pci_devinst *pi, int baridx,
	uint64_t offset, int size)
{
	struct virtio_softc *vs = pi->pi_arg;
	struct virtio_consts *vc;
	struct config_reg *cr;
	uint64_t virtio_config_size, max;
	const char *name;
	uint32_t newoff;
	uint32_t value;
	int error;

	if (vs->vs_flags & VIRTIO_USE_MSIX) {
		if (baridx == pci_msix_table_bar(pi) ||
		    baridx == pci_msix_pba_bar(pi)) {
			return (pci_emul_msix_tread(pi, offset, size));
		}
	}


	assert(baridx == 0);

	if (vs->vs_mtx)
		pthread_mutex_lock(vs->vs_mtx);

	vc = vs->vs_vc;
	name = vc->vc_name;
	value = size == 1 ? 0xff : size == 2 ? 0xffff : 0xffffffff;

	if (size != 1 && size != 2 && size != 4)
		goto bad;

	if (pci_msix_enabled(pi))
		virtio_config_size = VTCFG_R_CFG1;
	else
		virtio_config_size = VTCFG_R_CFG0;

	if (offset >= virtio_config_size) {





		newoff = (uint32_t) (offset - virtio_config_size);
		max = vc->vc_cfgsize ? vc->vc_cfgsize : 0x100000000;
		if ((newoff + ((unsigned) size)) > max)
			goto bad;
		error = (*vc->vc_cfgread)(DEV_SOFTC(vs), ((int) newoff), size, &value);
		if (!error)
			goto done;
	}

bad:
	cr = vi_find_cr((int) offset);
	if (cr == NULL || cr->cr_size != size) {
		if (cr != NULL) {

			fprintf(stderr,
			    "%s: read from %s: bad size %d\r\n",
			    name, cr->cr_name, size);
		} else {
			fprintf(stderr,
			    "%s: read from bad offset/size %jd/%d\r\n",
			    name, (uintmax_t)offset, size);
		}
		goto done;
	}

	switch (offset) {
	case VTCFG_R_HOSTCAP:
		value = (uint32_t) vc->vc_hv_caps;
		break;
	case VTCFG_R_GUESTCAP:
		value = vs->vs_negotiated_caps;
		break;
	case VTCFG_R_PFN:
		if (vs->vs_curq < vc->vc_nvq)
			value = vs->vs_queues[vs->vs_curq].vq_pfn;
		break;
	case VTCFG_R_QNUM:
		value = vs->vs_curq < vc->vc_nvq ?
		    vs->vs_queues[vs->vs_curq].vq_qsize : 0;
		break;
	case VTCFG_R_QSEL:
		value = (uint32_t) (vs->vs_curq);
		break;
	case VTCFG_R_QNOTIFY:
		value = 0;	
		break;
	case VTCFG_R_STATUS:
		value = vs->vs_status;
		break;
	case VTCFG_R_ISR:
		value = vs->vs_isr;
		vs->vs_isr = 0;		
		if (value)
			pci_lintr_deassert(pi);
		break;
	case VTCFG_R_CFGVEC:
		value = vs->vs_msix_cfg_idx;
		break;
	case VTCFG_R_QVEC:
		value = vs->vs_curq < vc->vc_nvq ?
		    vs->vs_queues[vs->vs_curq].vq_msix_idx :
		    VIRTIO_MSI_NO_VECTOR;
		break;
	}
done:
	if (vs->vs_mtx)
		pthread_mutex_unlock(vs->vs_mtx);
	return (value);
}

