void CalcProfileID(CIccIO *pIO, icProfileID *pProfileID)
{
  icUInt32Number nBlock;
  MD5_CTX context;
  icUInt8Number buffer[1024] = {0};


  size_t pos = pIO->Tell();


  size_t len = pIO->GetLength();
  pIO->Seek(0, icSeekSet);


  icMD5Init(&context);
  nBlock = 0;
  while(len) {
    size_t num = pIO->Read8(&buffer[0],1024);
    if (!nBlock) {  
      memset(buffer+44, 0, 4); 
      memset(buffer+64, 0, 4);  
      memset(buffer+84, 0, 16); 
    }
    icMD5Update(&context,buffer, (unsigned int) num);
    nBlock++;
    len -=num;
  }
  icMD5Final(&pProfileID->ID8[0],&context);


  pIO->Seek(pos, icSeekSet);
}

void CalcProfileID(CIccIO *pIO, icProfileID *pProfileID)
{
  icUInt32Number nBlock;
  MD5_CTX context;
  icUInt8Number buffer[1024] = {0};


  size_t pos = pIO->Tell();


  size_t len = pIO->GetLength();
  pIO->Seek(0, icSeekSet);


  icMD5Init(&context);
  nBlock = 0;
  while(len) {
    size_t num = pIO->Read8(&buffer[0],1024);
    if (num == 0)
        break;              
    if (!nBlock) {  
      memset(buffer+44, 0, 4); 
      memset(buffer+64, 0, 4);  
      memset(buffer+84, 0, 16); 
    }
    icMD5Update(&context,buffer, (unsigned int) num);
    nBlock++;
    len -= num;
  }
  icMD5Final(&pProfileID->ID8[0],&context);


  pIO->Seek(pos, icSeekSet);
}

icUInt32Number CIccXmlArrayType<T, Tsig>::ParseText(T* pBuf, icUInt32Number nSize, const char *szText)
{	
  icUInt32Number n = 0, b = 0;
  bool bInNum = false;
  char num[256] = {0};

  while ( (n < nSize) && *szText ) {
    if (icIsNumChar(*szText)) {
      if (!bInNum) {
        bInNum = true;
        b=0;
      }
      num[b] = *szText;

      if (b+2<sizeof(num))
        b++;
    }
    else if (bInNum) {
      num[b] = 0;
      if (!strncmp(num, "nan", 3) || !strncmp(num, "-nan", 4)) {
        pBuf[n] = (T)nanf(num);
      }
      else {
        pBuf[n] = (T)atof(num);
      }
      n++;
      bInNum = false;
    }
    szText++;
  }
  if ( bInNum && (n < nSize) ) {
    num[b] = 0;
    if (!strncmp(num, "nan", 3) || !strncmp(num, "-nan", 4)) {
      pBuf[n] = (T)nanf(num);
    }
    else {
      pBuf[n] = (T)atof(num);
    }
    n++;
  } 

  return n;
}

