bool CIccProfile::LoadTag(IccTagEntry *pTagEntry, CIccIO *pIO, bool bReadAll)
{
  if (!pTagEntry)
    return false;

  if (pTagEntry->pTag)
    return pTagEntry->pTag->ReadAll();

  if (pTagEntry->TagInfo.offset<sizeof(m_Header) ||
    !pTagEntry->TagInfo.size) {
    return false;
  }

  icTagTypeSignature sigType;


  if (pIO->Seek(pTagEntry->TagInfo.offset, icSeekSet)!= pTagEntry->TagInfo.offset)
    return false;

  if (!pIO->Read32(&sigType))
    return false;

  CIccTag *pTag = CIccTag::Create(sigType);

  if (!pTag)
    return false;




  if (pIO->Seek(pTagEntry->TagInfo.offset, icSeekSet)!= pTagEntry->TagInfo.offset) {
    delete pTag;
    return false;
  }

  if (!pTag->Read(pTagEntry->TagInfo.size, pIO, this)) {
    delete pTag;
    return false;
  }

  if (bReadAll) {
    if (!pTag->ReadAll()) {
      delete pTag;
      return false;
    }
  }

  switch(pTagEntry->TagInfo.sig) {
  case icSigAToB0Tag:
  case icSigAToB1Tag:
  case icSigAToB2Tag:
    if (pTag->IsMBBType())
      ((CIccMBB*)pTag)->SetColorSpaces(m_Header.colorSpace, m_Header.pcs);
    break;

  case icSigBToA0Tag:
  case icSigBToA1Tag:
  case icSigBToA2Tag:
    if (pTag->IsMBBType())
      ((CIccMBB*)pTag)->SetColorSpaces(m_Header.pcs, m_Header.colorSpace);
    break;

  case icSigGamutTag:
    if (pTag->IsMBBType())
      ((CIccMBB*)pTag)->SetColorSpaces(m_Header.pcs, icSigGamutData);
    break;

  case icSigNamedColor2Tag:
    if (pTag->GetTagArrayType()==icSigNamedColorArray) {
      CIccArrayNamedColor *pNamed = (CIccArrayNamedColor*)icGetTagArrayHandler(pTag);
      if (pNamed)
        pNamed->SetColorSpaces(m_Header.pcs, m_Header.colorSpace,
                               m_Header.spectralPCS,
                               &m_Header.spectralRange,
                               &m_Header.biSpectralRange);
    }
    else if (pTag->GetType()==icSigNamedColor2Type) {
      ((CIccTagNamedColor2*)pTag)->SetColorSpaces(m_Header.pcs, m_Header.colorSpace);
    }
    break;

  default:
    break;
  }

  pTagEntry->pTag = pTag;

  IccTagPtr TagPtr = {};

  TagPtr.ptr = pTag;

  m_TagVals.push_back(TagPtr);

  TagEntryList::iterator i;

  for (i=m_Tags.begin(); i!= m_Tags.end(); i++) {
    if (i->TagInfo.offset == pTagEntry->TagInfo.offset &&
        i->pTag != pTag)
      i->pTag = pTag; 
  }

  return true;
}

bool CIccProfile::LoadTag(IccTagEntry *pTagEntry, CIccIO *pIO, bool bReadAll)
{
  if (!pTagEntry)
    return false;

  if (pTagEntry->pTag)
    return pTagEntry->pTag->ReadAll();


  if (pTagEntry->TagInfo.offset<sizeof(m_Header) ||
    !pTagEntry->TagInfo.size) {
    return false;
  }



  if ( (pTagEntry->TagInfo.offset + pTagEntry->TagInfo.size) > pIO->GetLength())
    return false;

  icTagTypeSignature sigType;


  if (pIO->Seek(pTagEntry->TagInfo.offset, icSeekSet)!= pTagEntry->TagInfo.offset)
    return false;

  if (!pIO->Read32(&sigType))
    return false;

  CIccTag *pTag = CIccTag::Create(sigType);

  if (!pTag)
    return false;



  if (pIO->Seek(pTagEntry->TagInfo.offset, icSeekSet)!= pTagEntry->TagInfo.offset) {
    delete pTag;
    return false;
  }

  if (!pTag->Read(pTagEntry->TagInfo.size, pIO, this)) {
    delete pTag;
    return false;
  }

  if (bReadAll) {
    if (!pTag->ReadAll()) {
      delete pTag;
      return false;
    }
  }

  switch(pTagEntry->TagInfo.sig) {
  case icSigAToB0Tag:
  case icSigAToB1Tag:
  case icSigAToB2Tag:
    if (pTag->IsMBBType())
      ((CIccMBB*)pTag)->SetColorSpaces(m_Header.colorSpace, m_Header.pcs);
    break;

  case icSigBToA0Tag:
  case icSigBToA1Tag:
  case icSigBToA2Tag:
    if (pTag->IsMBBType())
      ((CIccMBB*)pTag)->SetColorSpaces(m_Header.pcs, m_Header.colorSpace);
    break;

  case icSigGamutTag:
    if (pTag->IsMBBType())
      ((CIccMBB*)pTag)->SetColorSpaces(m_Header.pcs, icSigGamutData);
    break;

  case icSigNamedColor2Tag:
    if (pTag->GetTagArrayType()==icSigNamedColorArray) {
      CIccArrayNamedColor *pNamed = (CIccArrayNamedColor*)icGetTagArrayHandler(pTag);
      if (pNamed)
        pNamed->SetColorSpaces(m_Header.pcs, m_Header.colorSpace,
                               m_Header.spectralPCS,
                               &m_Header.spectralRange,
                               &m_Header.biSpectralRange);
    }
    else if (pTag->GetType()==icSigNamedColor2Type) {
      ((CIccTagNamedColor2*)pTag)->SetColorSpaces(m_Header.pcs, m_Header.colorSpace);
    }
    break;

  default:
    break;
  }

  pTagEntry->pTag = pTag;

  IccTagPtr TagPtr = {};

  TagPtr.ptr = pTag;

  m_TagVals.push_back(TagPtr);

  TagEntryList::iterator i;

  for (i=m_Tags.begin(); i!= m_Tags.end(); i++) {
    if (i->TagInfo.offset == pTagEntry->TagInfo.offset &&
        i->pTag != pTag)
      i->pTag = pTag; 
  }

  return true;
}

icValidateStatus CIccMBB::Validate(std::string sigPath, std::string &sReport, const CIccProfile* pProfile) const
{
  icValidateStatus rv = CIccTag::Validate(sigPath, sReport, pProfile);

  CIccInfo Info;
  std::string sSigPathName = Info.GetSigPathName(sigPath);
  icSignature sig = icGetFirstSigPathSig(sigPath);

  if (!pProfile) {
    sReport += icMsgValidateWarning;
    sReport += sSigPathName;
    sReport += " - Tag validation incomplete: Pointer to profile unavailable.\n";
    rv = icMaxStatus(rv, icValidateWarning);
    return rv;
  }
  icUInt32Number nInput, nOutput;


  switch(sig) {
  case icSigAToB0Tag:
  case icSigAToB1Tag:
  case icSigAToB2Tag:
  case icSigAToB3Tag:
    {
      nInput = icGetSpaceSamples(pProfile->m_Header.colorSpace);
      if (m_nInput!=nInput) {
        sReport += icMsgValidateCriticalError;
        sReport += sSigPathName;
        sReport += " - Incorrect number of input channels.\n";
        rv = icMaxStatus(rv, icValidateCriticalError);
      }

      nOutput = icGetSpaceSamples(pProfile->m_Header.pcs);
      if (m_nOutput!=nOutput) {
        sReport += icMsgValidateCriticalError;
        sReport += sSigPathName;
        sReport += " - Incorrect number of output channels.\n";
        rv = icMaxStatus(rv, icValidateCriticalError);
      }

      break;
    }
  case icSigBToA0Tag:
  case icSigBToA1Tag:
  case icSigBToA2Tag:
  case icSigBToA3Tag:
    {
      nInput = icGetSpaceSamples(pProfile->m_Header.pcs);
      if (m_nInput!=nInput) {
        sReport += icMsgValidateCriticalError;
        sReport += sSigPathName;
        sReport += " - Incorrect number of input channels.\n";
        rv = icMaxStatus(rv, icValidateCriticalError);
      }

      nOutput = icGetSpaceSamples(pProfile->m_Header.colorSpace);
      if (m_nOutput!=nOutput) {
        sReport += icMsgValidateCriticalError;
        sReport += sSigPathName;
        sReport += " - Incorrect number of output channels.\n";
        rv = icMaxStatus(rv, icValidateCriticalError);
      }

      break;
    }
  case icSigHToS0Tag:
  case icSigHToS1Tag:
  case icSigHToS2Tag:
  case icSigHToS3Tag:
  {
    nInput = icGetSpaceSamples(pProfile->m_Header.pcs);
    if (m_nInput != nInput) {
      sReport += icMsgValidateCriticalError;
      sReport += sSigPathName;
      sReport += " - Incorrect number of input channels.\n";
      rv = icMaxStatus(rv, icValidateCriticalError);
    }

    nOutput = icGetSpaceSamples(pProfile->m_Header.pcs);
    if (m_nOutput != nOutput) {
      sReport += icMsgValidateCriticalError;
      sReport += sSigPathName;
      sReport += " - Incorrect number of output channels.\n";
      rv = icMaxStatus(rv, icValidateCriticalError);
    }

    break;
  }
  case icSigGamutTag:
    {
      nInput = 1;
      if (m_nInput!=nInput) {
        sReport += icMsgValidateCriticalError;
        sReport += sSigPathName;
        sReport += " - Incorrect number of input channels.\n";
        rv = icMaxStatus(rv, icValidateCriticalError);
      }

      nOutput = icGetSpaceSamples(pProfile->m_Header.colorSpace);
      if (m_nOutput!=nOutput) {
        sReport += icMsgValidateCriticalError;
        sReport += sSigPathName;
        sReport += " - Incorrect number of output channels.\n";
        rv = icMaxStatus(rv, icValidateCriticalError);
      }

      break;
    }
  default:
    {
      nInput = m_nInput;
      nOutput = m_nOutput;
    }
  }


  if (nInput!=nOutput) {
    if (!m_CLUT) {
      sReport += icMsgValidateCriticalError;
      sReport += sSigPathName;
      sReport += " - CLUT must be present.\n";
      rv = icMaxStatus(rv, icValidateCriticalError);          
    }
  }

  if (m_CLUT) {
    rv = icMaxStatus(rv, m_CLUT->Validate(sigPath, sReport, pProfile));
  }

  return rv;
}

