        parseStr += "Read error of (";
        parseStr += filename;
        parseStr += ")!\n";
        free(fbuf);
        delete file;
        return false;
      }
      delete file;

      if (!a.ParseTextArray(fbuf) || !a.GetSize()) {
        parseStr += "Parse error of (";
        parseStr += filename;
        parseStr += ")!\n";
        free(fbuf);
        return false;
      }
      free(fbuf);
    }
    else if (Tsig==icSigFloat16ArrayType && sizeof(T)==sizeof(icFloat16Number)) {
      icUInt32Number n = len/sizeof(icFloat16Number);
      this->SetSize(n);
      if (file->Read16(&this->m_Num[0], n)!=n) {
        delete file;
        return false;
      }
      delete file;
      return true;
    }
    else if (Tsig==icSigFloat16ArrayType && sizeof(T)==sizeof(icFloat32Number)) {
      icUInt32Number n = (icUInt32Number)(len/sizeof(icFloat32Number));
      this->SetSize(n);
      if (file->ReadFloat16Float(&this->m_Num[0], n)!=n) {
        delete file;
        return false;
      }
      delete file;
      return true;
    }
    else if (Tsig==icSigFloat32ArrayType && sizeof(T)==sizeof(icFloat32Number)) {
      icUInt32Number n =  (icUInt32Number)(len/sizeof(icFloat32Number));
      this->SetSize(n);
      if (file->ReadFloat32Float(&this->m_Num[0], n)!=n) {
        delete file;
        return false;
      }
      delete file;
      return true;
    }
    else if (Tsig==icSigFloat64ArrayType && sizeof(T)==sizeof(icFloat64Number)) {
      icUInt32Number n =  (icUInt32Number)(len/sizeof(icFloat64Number));
      this->SetSize(n);
      if (file->Read64(&this->m_Num[0], n)!=n) {
        delete file;
        return false;
      }
      delete file;
      return true;

    }
    else {
      delete file;
      parseStr += "Unsupported file parsing type!\n";
      return false;
    }
  }
  else {
    if (!pNode)
      return false;

    pNode = pNode->children;

    if (!a.ParseArray(pNode) || !a.GetSize()) {   
      return false;
    }
  }

  icUInt32Number i, n = a.GetSize();
  T *buf = a.GetBuf();

  this->SetSize(n);

  for (i=0; i<n; i++) {
    this->m_Num[i] = buf[i];
  }
  return true;
}

bool CIccTagNamedColor2::Read(icUInt32Number size, CIccIO *pIO)
{
  icTagTypeSignature sig;
  icUInt32Number nNum, nCoords;

  icUInt32Number nTagHdrSize = sizeof(icTagTypeSignature) + 
                               sizeof(icUInt32Number) + 
                               sizeof(icUInt32Number) + 
                               sizeof(icUInt32Number) + 
                               sizeof(icUInt32Number) + 
                               sizeof(m_szPrefix) + 
                               sizeof(m_szSufix); 
  if (nTagHdrSize > size)
    return false;

  if (!pIO) {
    return false;
  }

  if (!pIO->Read32(&sig) ||
      !pIO->Read32(&m_nReserved) ||
      !pIO->Read32(&m_nVendorFlags) ||
      !pIO->Read32(&nNum) ||
      !pIO->Read32(&nCoords) ||
      pIO->Read8(m_szPrefix, sizeof(m_szPrefix))!=sizeof(m_szPrefix) ||
      pIO->Read8(m_szSufix, sizeof(m_szSufix))!=sizeof(m_szSufix)) {
    return false;
  }

  size -= nTagHdrSize;

  size_t nCount = size / (32+(3+(size_t)nCoords)*sizeof(icUInt16Number));

  if (nCount < (size_t)nNum)
    return false;

  if (!SetSize(nNum, nCoords))
    return false;

  icUInt32Number i;
  SIccNamedColorEntry *pNamedColor=m_NamedColor;

  for (i=0; i<nNum; i++) {
    if (pIO->Read8(&pNamedColor->rootName, sizeof(pNamedColor->rootName))!=sizeof(pNamedColor->rootName) ||
        pIO->ReadUInt16Float(&pNamedColor->pcsCoords, 3)!=3)
      return false;
    if (nCoords) {
      if (pIO->ReadUInt16Float(&pNamedColor->deviceCoords, nCoords)!= nCoords)
        return false;
    }
    pNamedColor = (SIccNamedColorEntry*)((icChar*)pNamedColor + m_nColorEntrySize);
  }

  return true;
}

