	LWCHAR ch;
{
	if (pansi->hlink)
	{

		if (ch == '\7')
			return ANSI_END;
		if (pansi->prev_esc)
            return (ch == '\\') ? ANSI_END : ANSI_ERR;
		pansi->prev_esc = (ch == ESC);
		return ANSI_MID;
	}
	if (pansi->hindex >= 0)
	{
		static char hlink_prefix[] = ESCS "]8;";
