	} else if (pk_alg != gnutls_privkey_get_pk_algorithm(privkey, NULL)) {
		SIGN_ERROR("Alg mismatch with signing key"); 
	}

	if (gnutls_privkey_sign_data(privkey, alg, flags,
                                &body_dat, &sig_dat))
		SIGN_ERROR("Failed to sign token"); 

	if (pk_alg == GNUTLS_PK_EC) {

		if (gnutls_decode_rs_value(&sig_dat, &r, &s))
			SIGN_ERROR("Error decoding EC key"); 


		if (jwt->alg == JWT_ALG_ES256 || jwt->alg == JWT_ALG_ES256K)
			adj = 32;
		else if (jwt->alg == JWT_ALG_ES384)
			adj = 48;
		else if (jwt->alg == JWT_ALG_ES512)
			adj = 66;
		else
			SIGN_ERROR("Unknown EC algorithm");

		if (r.size > adj)
			r_padding = r.size - adj;
		else if (r.size < adj)
			r_out_padding = adj - r.size;

		if (s.size > adj)
			s_padding = s.size - adj;
		else if (s.size < adj)
			s_out_padding = adj - s.size;

		out_size = adj << 1;

		*out = jwt_malloc(out_size);
		if (*out == NULL)
			SIGN_ERROR("Out of memory"); 

		memset(*out, 0, out_size);

		memcpy(*out + r_out_padding, r.data + r_padding, r.size - r_padding);
		memcpy(*out + (r.size - r_padding + r_out_padding) + s_out_padding,
		       s.data + s_padding, (s.size - s_padding));

		*len = (r.size - r_padding + r_out_padding) +
			(s.size - s_padding + s_out_padding);
		gnutls_free(r.data);
		gnutls_free(s.data);
	} else {

		*out = jwt_malloc(sig_dat.size);
		if (*out == NULL)
			SIGN_ERROR("Out of memory"); 


		memcpy(*out, sig_dat.data, sig_dat.size);
		*len = sig_dat.size;
	}


	gnutls_free(sig_dat.data);

sign_clean_privkey:
	gnutls_privkey_deinit(privkey);

	if (jwt->error)
		jwt_freemem(*out); 

	return jwt->error;
}

static size_t header_cb(char *buf, size_t size, size_t nmemb, void *ctx)
{
	size_t total_size = size * nmemb;
	struct jwks_data *data = ctx;

	if (strncasecmp(buf, "Content-Length:", 15))
		return total_size;

	data->alloc_size = (size_t)atol(buf + 15);
	data->buf = jwt_malloc(data->alloc_size + 1);
	if (!data->buf)
		return 0; 

	data->size = 0;
	data->buf[0] = '\0';

	return total_size;
}

static size_t header_cb(char *buf, size_t size, size_t nmemb, void *ctx)
{
	size_t total_size = size * nmemb;
	struct jwks_data *data = ctx;
	long content_length;
	char *endptr;

	if (strncasecmp(buf, "Content-Length:", 15))
		return total_size;

	content_length = strtol(buf + 15, &endptr, 10);
	if (endptr == buf + 15 || content_length <= 0 ||
	    content_length > JWKS_MAX_RESPONSE_SIZE)
		return 0;

	data->alloc_size = (size_t)content_length;
	data->buf = jwt_malloc(data->alloc_size + 1);
	if (!data->buf)
		return 0; 

	data->size = 0;
	data->buf[0] = '\0';

	return total_size;
}

const jwk_item_t *jwks_item_get(const jwk_set_t *jwk_set, size_t index)
{
	jwk_item_t *item = NULL;
	size_t i = 0;

	list_for_each_entry(item, &jwk_set->head, node) {
		if (i == index)
			return item;
		i++;
	}

	return NULL;
}

