          else if (len >= 1 && c == 0xe0 && (unsigned char)str[1] < 0xa0)
            {
              LOG_WARN ("utf-8: NON_SHORTEST %s", str);
            }
          else if (len >= 2)
            {
              wstr[i++] = ((c & 0x0f) << 12) | ((str[1] & 0x3f) << 6)
                | (str[2] & 0x3f);
              str++;
              str++;
              len--;
              len--;
            }
        }

    }
  return wstr;
}

int
decode_preR13_auxheader (Bit_Chain *restrict dat, Dwg_Data *restrict dwg)
{
  int error = 0;
  BITCODE_RS crc, crcc;
  Dwg_AuxHeader *_obj = &dwg->auxheader;

  LOG_TRACE ("\nAUXHEADER: @0x%lx\n", dat->byte);
  error |= decode_preR13_sentinel(DWG_SENTINEL_R11_AUX_HEADER_BEGIN,
                                 "DWG_SENTINEL_R11_AUX_HEADER_BEGIN", dat, dwg);
  FIELD_RS (num_auxheader_variables, 0);
  FIELD_RS (auxheader_size, 0);
  FIELD_RLx (entities_start, 0);
  if (_obj->entities_start != dwg->header.entities_start)
    {
      LOG_WARN ("entities_start %x/%x", _obj->entities_start, dwg->header.entities_start);
    }
  FIELD_RLx (entities_end, 0);
  if (_obj->entities_end != dwg->header.entities_end)
    {
      LOG_WARN ("entities_end %x/%x", _obj->entities_end, dwg->header.entities_end);
    }
  FIELD_RLx (blocks_start, 0);
  if (_obj->blocks_start != dwg->header.blocks_start)
    {
      LOG_WARN ("blocks_start %x/%x", _obj->blocks_start, dwg->header.blocks_start);
    }
  FIELD_RLx (extras_start, 0);
  if (_obj->extras_start != dwg->header.extras_start)
    {
      LOG_WARN ("extras_start %x/%x", _obj->extras_start, dwg->header.extras_start);
    }
  FIELD_RS (R11_HANDLING, 0);
  {
    _obj->R11_HANDSEED = (BITCODE_H)calloc(1, sizeof(Dwg_Object_Ref));
    _obj->R11_HANDSEED->handleref.code = 0;
    _obj->R11_HANDSEED->handleref.size = 8;
    _obj->R11_HANDSEED->handleref.value = htobe64 (bit_read_RLL (dat));
    _obj->R11_HANDSEED->absolute_ref = _obj->R11_HANDSEED->handleref.value;
    LOG_TRACE ("R11_HANDSEED: " FORMAT_H " [H 5]\n",
               ARGS_H (_obj->R11_HANDSEED->handleref));
  }
  FIELD_RS (num_aux_tables, 0);
  decode_preR13_section_chk (SECTION_BLOCK, dat, dwg);
  decode_preR13_section_chk (SECTION_LAYER, dat, dwg);
  decode_preR13_section_chk (SECTION_STYLE, dat, dwg);
  decode_preR13_section_chk (SECTION_LTYPE, dat, dwg);
  decode_preR13_section_chk (SECTION_VIEW, dat, dwg);
  if (dwg->header.num_sections >= SECTION_VPORT)
    {
      decode_preR13_section_chk (SECTION_UCS, dat, dwg);
      decode_preR13_section_chk (SECTION_VPORT, dat, dwg);
    }
  if (dwg->header.num_sections >= SECTION_APPID)
    {
      decode_preR13_section_chk (SECTION_APPID, dat, dwg);
    }
  if (dwg->header.num_sections >= SECTION_VX)
    {
      decode_preR13_section_chk (SECTION_DIMSTYLE, dat, dwg);
      decode_preR13_section_chk (SECTION_VX, dat, dwg);
    }
  FIELD_RLx (auxheader_address, 0);
  crcc = bit_calc_CRC (
      0xC0C1,
      &dat->chain[_obj->auxheader_address + 16], 
      _obj->auxheader_size - 2);                 
  crc = bit_read_RS (dat);
  LOG_TRACE ("crc: %04X [RSx] from 0x%x-0x%lx\n", crc,
             _obj->auxheader_address + 16, dat->byte - 2);
  if (crc != crcc)
    {
      LOG_ERROR ("AUX header CRC mismatch %04X <=> %04X", crc, crcc);
      error |= DWG_ERR_WRONGCRC;
    }
  error
      |= decode_preR13_sentinel (DWG_SENTINEL_R11_AUX_HEADER_END,
                                 "DWG_SENTINEL_R11_AUX_HEADER_END", dat, dwg);
  LOG_TRACE ("\n");

  return error;
}

int
decode_preR13_auxheader (Bit_Chain *restrict dat, Dwg_Data *restrict dwg)
{
  int error = 0;
  BITCODE_RS crc, crcc;
  Dwg_AuxHeader *_obj = &dwg->auxheader;
  unsigned long pos = dat->byte;

  LOG_TRACE ("\nAUXHEADER: @0x%lx\n", dat->byte);
  error |= decode_preR13_sentinel(DWG_SENTINEL_R11_AUX_HEADER_BEGIN,
                                 "DWG_SENTINEL_R11_AUX_HEADER_BEGIN", dat, dwg);
  FIELD_RS (num_auxheader_variables, 0);
  FIELD_RS (auxheader_size, 0);
  FIELD_RLx (entities_start, 0);
  if (_obj->entities_start != dwg->header.entities_start)
    {
      LOG_WARN ("entities_start %x/%x", _obj->entities_start, dwg->header.entities_start);
    }
  FIELD_RLx (entities_end, 0);
  if (_obj->entities_end != dwg->header.entities_end)
    {
      LOG_WARN ("entities_end %x/%x", _obj->entities_end, dwg->header.entities_end);
    }
  FIELD_RLx (blocks_start, 0);
  if (_obj->blocks_start != dwg->header.blocks_start)
    {
      LOG_WARN ("blocks_start %x/%x", _obj->blocks_start, dwg->header.blocks_start);
    }
  FIELD_RLx (extras_start, 0);
  if (_obj->extras_start != dwg->header.extras_start)
    {
      LOG_WARN ("extras_start %x/%x", _obj->extras_start, dwg->header.extras_start);
    }
  FIELD_RS (R11_HANDLING, 0);
  {
    _obj->R11_HANDSEED = (BITCODE_H)calloc(1, sizeof(Dwg_Object_Ref));
    _obj->R11_HANDSEED->handleref.code = 0;
    _obj->R11_HANDSEED->handleref.size = 8;
    _obj->R11_HANDSEED->handleref.value = htobe64 (bit_read_RLL (dat));
    _obj->R11_HANDSEED->absolute_ref = _obj->R11_HANDSEED->handleref.value;
    LOG_TRACE ("R11_HANDSEED: " FORMAT_H " [H 5]\n",
               ARGS_H (_obj->R11_HANDSEED->handleref));
  }
  FIELD_RS (num_aux_tables, 0);
  decode_preR13_section_chk (SECTION_BLOCK, dat, dwg);
  decode_preR13_section_chk (SECTION_LAYER, dat, dwg);
  decode_preR13_section_chk (SECTION_STYLE, dat, dwg);
  decode_preR13_section_chk (SECTION_LTYPE, dat, dwg);
  decode_preR13_section_chk (SECTION_VIEW, dat, dwg);
  if (dwg->header.num_sections >= SECTION_VPORT)
    {
      decode_preR13_section_chk (SECTION_UCS, dat, dwg);
      decode_preR13_section_chk (SECTION_VPORT, dat, dwg);
    }
  if (dwg->header.num_sections >= SECTION_APPID)
    {
      decode_preR13_section_chk (SECTION_APPID, dat, dwg);
    }
  if (dwg->header.num_sections >= SECTION_VX)
    {
      decode_preR13_section_chk (SECTION_DIMSTYLE, dat, dwg);
      decode_preR13_section_chk (SECTION_VX, dat, dwg);
    }
  FIELD_RLx (auxheader_address, 0);
  if (_obj->auxheader_address < pos
      || _obj->auxheader_address + 16 > dat->size
      || _obj->auxheader_address + _obj->auxheader_size > dat->size)
    {
      LOG_ERROR ("Invalid auxheader_address %04X", _obj->auxheader_address);
      error |= DWG_ERR_WRONGCRC;
      return error;
    }
  if (_obj->auxheader_address != pos)
    {
      LOG_WARN ("Invalid auxheader_address %04X", _obj->auxheader_address);
      error |= DWG_ERR_WRONGCRC;
    }
  else
    {
      crcc = bit_calc_CRC (0xC0C1,

                           &dat->chain[_obj->auxheader_address + 16],

                           _obj->auxheader_size - 2); 
      crc = bit_read_RS (dat);
      LOG_TRACE ("crc: %04X [RSx] from 0x%x-0x%lx\n", crc,
                 _obj->auxheader_address + 16, dat->byte - 2);
      if (crc != crcc)
        {
          LOG_ERROR ("AUX header CRC mismatch %04X <=> %04X", crc, crcc);
          error |= DWG_ERR_WRONGCRC;
        }
    }
  error
      |= decode_preR13_sentinel (DWG_SENTINEL_R11_AUX_HEADER_END,
                                 "DWG_SENTINEL_R11_AUX_HEADER_END", dat, dwg);
  LOG_TRACE ("\n");

  return error;
}

static void
box_blur_line (gint box_width, gint even_offset,
               guchar *src, guchar *dest,
               gint len, gint bpp)
{
    gint  i;
    gint  lead;    
    gint  output;  
    gint  trail;   

    gint  *ac;     

    ac = g_new0 (gint, bpp);










    lead = 0;

    if (box_width % 2 != 0) {

        output = lead - (box_width - 1) / 2;
        trail  = lead - box_width;
    } else {

        if (even_offset == 1) {

            output = lead + 1 - box_width / 2;
            trail  = lead - box_width;
        } else if (even_offset == -1) {

            output = lead - box_width / 2;
            trail  = lead - box_width;
        } else {

            g_assert_not_reached ();
        }
    }


    for (i = 0; i < bpp; i++)
        ac[i] = 0;



    while (output < len) {



        guint coverage = (lead < len ? lead : len - 1) - (trail >= 0 ? trail : -1);

#ifdef READABLE_BOXBLUR_CODE




        for (i = 0; i < bpp; i++) {


            if (lead < len)
                ac[i] += src[bpp * lead + i];



            if (trail >= 0)
                ac[i] -= src[bpp * trail + i];






            if (output >= 0)
                dest[bpp * output + i] = (ac[i] + (coverage >> 1)) / coverage;
        }
#endif


        if (lead < len) {
            if (trail >= 0) {



                for (i = 0; i < bpp; i++) {
                    ac[i] += src[bpp * lead + i];
                    ac[i] -= src[bpp * trail + i];
                    dest[bpp * output + i] = (ac[i] + (coverage >> 1)) / coverage;
                }
            } else if (output >= 0) {



                for (i = 0; i < bpp; i++) {
                    ac[i] += src[bpp * lead + i];
                    dest[bpp * output + i] = (ac[i] + (coverage >> 1)) / coverage;
                }
            } else {


                for (i = 0; i < bpp; i++)
                    ac[i] += src[bpp * lead + i];
            }
        } else if (trail >= 0) {



            for (i = 0; i < bpp; i++) {
                ac[i] -= src[bpp * trail + i];
                dest[bpp * output + i] = (ac[i] + (coverage >> 1)) / coverage;
            }
        } else if (output >= 0) {


            for (i = 0; i < bpp; i++)
                dest[bpp * output + i] = (ac[i] + (coverage >> 1)) / coverage;
        }

        lead++;
        output++;
        trail++;
    }

    g_free (ac);
}

