static int
vips_foreign_load_csv_build(VipsObject *object)
{
	VipsForeignLoadCsv *csv = (VipsForeignLoadCsv *) object;

	int i;
	const char *p;

	if (!(csv->sbuf = vips_sbuf_new_from_source(csv->source)))
		return -1;



	for (i = 0; i < 256; i++) {
		csv->whitemap[i] = 0;
		csv->sepmap[i] = 0;
	}
	for (p = csv->whitespace; *p; p++)
		csv->whitemap[(int) *p] = 1;
	for (p = csv->separator; *p; p++)
		csv->sepmap[(int) *p] = 1;



	csv->sepmap[(int) '\n'] = 0;
	csv->whitemap[(int) '\n'] = 0;

	return VIPS_OBJECT_CLASS(vips_foreign_load_csv_parent_class)
		->build(object);
}

static int
vips_foreign_load_csv_build(VipsObject *object)
{
	VipsForeignLoadCsv *csv = (VipsForeignLoadCsv *) object;

	int i;
	const char *p;

	if (!g_str_is_ascii(csv->whitespace) ||
		!g_str_is_ascii(csv->separator)) {
		vips_error("csvload", "%s",
			_("whitespace and separator must be ASCII"));
		return -1;
	}

	if (!(csv->sbuf = vips_sbuf_new_from_source(csv->source)))
		return -1;



	for (i = 0; i < 256; i++) {
		csv->whitemap[i] = 0;
		csv->sepmap[i] = 0;
	}
	for (p = csv->whitespace; *p; p++)
		csv->whitemap[(int) *p] = 1;
	for (p = csv->separator; *p; p++)
		csv->sepmap[(int) *p] = 1;



	csv->sepmap[(int) '\n'] = 0;
	csv->whitemap[(int) '\n'] = 0;

	return VIPS_OBJECT_CLASS(vips_foreign_load_csv_parent_class)
		->build(object);
}

static int
vips_unpremultiply_build(VipsObject *object)
{
	VipsObjectClass *class = VIPS_OBJECT_GET_CLASS(object);
	VipsConversion *conversion = VIPS_CONVERSION(object);
	VipsUnpremultiply *unpremultiply = (VipsUnpremultiply *) object;
	VipsImage **t = (VipsImage **) vips_object_local_array(object, 1);

	VipsImage *in;

	if (VIPS_OBJECT_CLASS(vips_unpremultiply_parent_class)->build(object))
		return -1;

	in = unpremultiply->in;

	if (vips_image_decode(in, &t[0]))
		return -1;
	in = t[0];



	if (in->Bands == 1)
		return vips_image_write(in, conversion->out);

	if (vips_check_noncomplex(class->nickname, in))
		return -1;

	if (vips_image_pipelinev(conversion->out,
			VIPS_DEMAND_STYLE_THINSTRIP, in, NULL))
		return -1;




	if (!vips_object_argument_isset(object, "max_alpha"))
		unpremultiply->max_alpha = vips_interpretation_max_alpha(in->Type); 



	if (!vips_object_argument_isset(object, "alpha_band"))
		unpremultiply->alpha_band = in->Bands - 1; 

	if (in->BandFmt == VIPS_FORMAT_DOUBLE)
		conversion->out->BandFmt = VIPS_FORMAT_DOUBLE;
	else
		conversion->out->BandFmt = VIPS_FORMAT_FLOAT;

	if (vips_image_generate(conversion->out,
			vips_start_one, vips_unpremultiply_gen, vips_stop_one,
			in, unpremultiply))
		return -1;

	return 0;
}

static int
vips_unpremultiply_build(VipsObject *object)
{
	VipsObjectClass *class = VIPS_OBJECT_GET_CLASS(object);
	VipsConversion *conversion = VIPS_CONVERSION(object);
	VipsUnpremultiply *unpremultiply = (VipsUnpremultiply *) object;
	VipsImage **t = (VipsImage **) vips_object_local_array(object, 1);

