                lex.PopIncludeContinue();
            } else if (!IsNext(T_LINEFEED)) {
                break;
            }
            if (Either(T_ENDOFFILE, T_DEDENT)) break;
        }
        if (terminator != T_NONE) Expect(terminator);
        if (!block->Arity()) {

            Error("block can\'t be empty");
        }
        auto b = block->children.back();
