            if (terminator == T_ENDOFFILE) block->Add(new IntConstant(lex, 0));
            else Error("last expression in block can\'t be a definition");
        }
        CleanupStatements(block);
    }

inline string TypeName(UnTypeRef type, bool tuple_brackets) {
    switch (type->t) {
        case V_STRUCT_NUM: {
            auto nvt = SymbolTable::GetVectorName(type->ns->t, type->ns->flen);
            if (nvt) return nvt;

            return type->ns->t == V_INT ? "intN" : "floatN";
        }
        case V_STRUCT_R:
        case V_STRUCT_S:
        case V_CLASS: {
            string s = type->udt->name;
            if (type->udt->unnamed_specialization && !type->udt->bound_generics.empty()) {
                s += "<";
                for (auto [i, t] : enumerate(type->udt->bound_generics)) {
                    if (i) s += ", ";
                    s += TypeName(t);
                }
                s += ">";
            }
            return s;
        }
        case V_UUDT: {
            string s = type->spec_udt->gudt->name;
            if (!type->spec_udt->specializers.empty()) {

                s += "<";
                for (auto [i, t] : enumerate(type->spec_udt->specializers)) {
                    if (i) s += ", ";
                    s += TypeName(t);
                }
                s += ">";
            }
            return s;
        }
        case V_VECTOR:
            return type->Element()->t == V_VAR
                        ? "[]"
                        : "[" + TypeName(type->Element()) + "]";
        case V_FUNCTION:
            return type->sf
                ? Signature(*type->sf)
                : "function";

        case V_NIL:
            return type->Element()->t == V_VAR
                ? "nil"
                : TypeName(type->Element()) + "?";
        case V_TUPLE: {
            string s;
            if (tuple_brackets) s += "(";
            for (auto [i, te] : enumerate(*type->tup)) {
                if (i) s += ", ";
                s += TypeName(te.type);
            }
            if (tuple_brackets) s += ")";
            return s;
        }
        case V_INT:
            return type->e ? type->e->name : "int";
        case V_TYPEID:
            return "typeid(" + TypeName(type->sub) + ")";
        case V_TYPEVAR:
            return string(type->tv->name);
        case V_RESOURCE:
            return type->rt ? cat("resource<", type->rt->name, ">") : "resource";
        case V_STRING:
            return "string";
        case V_FLOAT:
            return "float";
        case V_VOID:
            return "void";
        case V_VAR:
            return "unknown";
        case V_UNDEFINED:
            return "undefined";
        case V_ANY:
            return "any";
        default:
            return "<internal-error-type>";
    }
}

