nebula::cpp2::ErrorCode DownloadJobExecutor::check() {
  if (paras_.size() != 1) {
    return nebula::cpp2::ErrorCode::E_INVALID_JOB;
  }

  auto& url = paras_[0];
  std::string hdfsPrefix = "hdfs://";
  if (url.find(hdfsPrefix) != 0) {
    LOG(ERROR) << "URL should start with " << hdfsPrefix;
    return nebula::cpp2::ErrorCode::E_INVALID_JOB;
  }

  auto u = url.substr(hdfsPrefix.size(), url.size());
  std::vector<folly::StringPiece> tokens;
  folly::split(":", u, tokens);
  if (tokens.size() == 2) {
    host_ = std::make_unique<std::string>(tokens[0]);
    int32_t position = tokens[1].find_first_of("/");
    if (position != -1) {
      try {
        port_ = folly::to<int32_t>(tokens[1].toString().substr(0, position).c_str());
      } catch (const std::exception& ex) {
        LOG(ERROR) << "URL's port parse failed: " << url;
        return nebula::cpp2::ErrorCode::E_INVALID_JOB;
      }
      path_ =
          std::make_unique<std::string>(tokens[1].toString().substr(position, tokens[1].size()));
    } else {
      LOG(ERROR) << "URL Parse Failed: " << url;
      return nebula::cpp2::ErrorCode::E_INVALID_JOB;
    }
  } else {
    LOG(ERROR) << "URL Parse Failed: " << url;
    return nebula::cpp2::ErrorCode::E_INVALID_JOB;
  }

  return nebula::cpp2::ErrorCode::SUCCEEDED;
}

nebula::cpp2::ErrorCode DownloadJobExecutor::check() {
  if (paras_.size() != 1) {
    return nebula::cpp2::ErrorCode::E_INVALID_JOB;
  }

  auto& url = paras_[0];
  std::string hdfsPrefix = "hdfs://";
  if (url.find(hdfsPrefix) != 0) {
    LOG(ERROR) << "URL should start with " << hdfsPrefix;
    return nebula::cpp2::ErrorCode::E_INVALID_JOB;
  }

  auto u = url.substr(hdfsPrefix.size(), url.size());
  std::vector<std::string> tokens;
  folly::split(":", u, tokens);
  if (tokens.size() == 2) {
    if (!NetworkUtils::validateIP(tokens[0]).ok()) {
      LOG(ERROR) << "Illegal hdfs host: " << url;
      return nebula::cpp2::ErrorCode::E_INVALID_JOB;
    }
    host_ = std::make_unique<std::string>(tokens[0]);
    auto position = tokens[1].find_first_of("/");
    if (position != std::string::npos) {
      try {
        port_ = folly::to<int32_t>(tokens[1].substr(0, position).c_str());
      } catch (const std::exception& ex) {
        LOG(ERROR) << "URL's port parse failed: " << url;
        return nebula::cpp2::ErrorCode::E_INVALID_JOB;
      }
      auto path = tokens[1].substr(position, tokens[1].size());

      const std::regex pattern("^/[-_/0-9a-zA-Z]*$");
      if (!std::regex_match(path, pattern)) {
        LOG(ERROR) << "Illegal hdfs path: " << url;
        return nebula::cpp2::ErrorCode::E_INVALID_JOB;
      }
      path_ = std::make_unique<std::string>(path);
    } else {
      LOG(ERROR) << "URL Parse Failed: " << url;
      return nebula::cpp2::ErrorCode::E_INVALID_JOB;
    }
  } else {
    LOG(ERROR) << "URL Parse Failed: " << url;
    return nebula::cpp2::ErrorCode::E_INVALID_JOB;
  }

  return nebula::cpp2::ErrorCode::SUCCEEDED;
}

void SetFlagsHandler::onEOM() noexcept {
  folly::dynamic flags;
  folly::dynamic reply;
  try {
    if (!body_) {
      LOG(ERROR) << "Got an empty body";
      err_ = HttpCode::E_UNPROCESSABLE;
    } else {
      std::string body = body_->moveToFbString().toStdString();
      flags = folly::parseJson(body);
      if (flags.empty()) {
        err_ = HttpCode::E_UNPROCESSABLE;
      }
    }
  } catch (const std::exception &e) {
    LOG(ERROR) << "Fail to update flags: " << e.what();
    err_ = HttpCode::E_UNPROCESSABLE;
  }
  switch (err_) {
    case HttpCode::E_UNSUPPORTED_METHOD:
      reply = folly::dynamic::object("errorMessage", "Unsupported method");
      ResponseBuilder(downstream_)
          .status(WebServiceUtils::to(HttpStatusCode::METHOD_NOT_ALLOWED),
                  WebServiceUtils::toString(HttpStatusCode::METHOD_NOT_ALLOWED))
          .body(folly::toPrettyJson(reply))
          .sendWithEOM();
      return;
    case HttpCode::E_UNPROCESSABLE:
      reply = folly::dynamic::object("errorMessage", "Bad request");
      ResponseBuilder(downstream_)
          .status(WebServiceUtils::to(HttpStatusCode::BAD_REQUEST),
                  WebServiceUtils::toString(HttpStatusCode::BAD_REQUEST))
          .body(folly::toPrettyJson(reply))
          .sendWithEOM();
      return;
    default:
      break;
  }

  folly::dynamic failedOptions = folly::dynamic::array();
  for (auto &item : flags.items()) {
    try {
      const std::string &name = item.first.asString();
      const std::string &value = item.second.asString();
      const std::string &newValue = gflags::SetCommandLineOption(name.c_str(), value.c_str());
      if (newValue.empty()) {
        failedOptions.push_back(name);
      }
    } catch (const std::exception &e) {
      LOG(ERROR) << "Fail to update flags: " << e.what();
      reply = folly::dynamic::object("errorMessage", "Bad request parameter");
      ResponseBuilder(downstream_)
          .status(WebServiceUtils::to(HttpStatusCode::BAD_REQUEST),
                  WebServiceUtils::toString(HttpStatusCode::BAD_REQUEST))
          .body(folly::toPrettyJson(reply))
          .sendWithEOM();
      return;
    }
  }
  reply = failedOptions.empty() ? folly::dynamic::object("errCode", 0)
                                : folly::dynamic::object("failedOptions", failedOptions);
  ResponseBuilder(downstream_)
      .status(WebServiceUtils::to(HttpStatusCode::OK),
              WebServiceUtils::toString(HttpStatusCode::OK))
      .body(folly::toPrettyJson(reply))
      .sendWithEOM();
}

void SetFlagsHandler::onEOM() noexcept {
  folly::dynamic flags;
  folly::dynamic reply;
  try {
    if (!body_) {
      LOG(ERROR) << "Got an empty body";
      err_ = HttpCode::E_UNPROCESSABLE;
    } else {
      std::string body = body_->moveToFbString().toStdString();
      flags = folly::parseJson(body);
      if (flags.empty()) {
        err_ = HttpCode::E_UNPROCESSABLE;
      }
    }
  } catch (const std::exception &e) {
    LOG(ERROR) << "Fail to update flags: " << e.what();
    err_ = HttpCode::E_UNPROCESSABLE;
  }
  switch (err_) {
    case HttpCode::E_UNSUPPORTED_METHOD:
      reply = folly::dynamic::object("errorMessage", "Unsupported method");
      ResponseBuilder(downstream_)
          .status(WebServiceUtils::to(HttpStatusCode::METHOD_NOT_ALLOWED),
                  WebServiceUtils::toString(HttpStatusCode::METHOD_NOT_ALLOWED))
          .body(folly::toPrettyJson(reply))
          .sendWithEOM();
      return;
    case HttpCode::E_UNPROCESSABLE:
      reply = folly::dynamic::object("errorMessage", "Bad request");
      ResponseBuilder(downstream_)
          .status(WebServiceUtils::to(HttpStatusCode::BAD_REQUEST),
                  WebServiceUtils::toString(HttpStatusCode::BAD_REQUEST))
          .body(folly::toPrettyJson(reply))
          .sendWithEOM();
      return;
    default:
      break;
  }

  folly::dynamic failedOptions = folly::dynamic::array();
  for (auto &item : flags.items()) {
    try {
      const std::string &name = item.first.asString();
      if (name == "enable_authorize") {
        LOG(ERROR) << "Modifying enable_authorize is not allowed";
        ResponseBuilder(downstream_)
            .status(WebServiceUtils::to(HttpStatusCode::BAD_REQUEST),
                    WebServiceUtils::toString(HttpStatusCode::BAD_REQUEST))
            .sendWithEOM();
        return;
      }
      const std::string &value = item.second.asString();
      const std::string &newValue = gflags::SetCommandLineOption(name.c_str(), value.c_str());
      if (newValue.empty()) {
        failedOptions.push_back(name);
      }
    } catch (const std::exception &e) {
      LOG(ERROR) << "Fail to update flags: " << e.what();
      reply = folly::dynamic::object("errorMessage", "Bad request parameter");
      ResponseBuilder(downstream_)
          .status(WebServiceUtils::to(HttpStatusCode::BAD_REQUEST),
                  WebServiceUtils::toString(HttpStatusCode::BAD_REQUEST))
          .body(folly::toPrettyJson(reply))
          .sendWithEOM();
      return;
    }
  }
  reply = failedOptions.empty() ? folly::dynamic::object("errCode", 0)
                                : folly::dynamic::object("failedOptions", failedOptions);
  ResponseBuilder(downstream_)
      .status(WebServiceUtils::to(HttpStatusCode::OK),
              WebServiceUtils::toString(HttpStatusCode::OK))
      .body(folly::toPrettyJson(reply))
      .sendWithEOM();
}

int m_authenticate(struct Client* cptr, struct Client* sptr, int parc, char* parv[])
{
  struct Client* acptr;
  int first = 0;
  char realhost[HOSTLEN + 3];
  char *hoststr = (cli_sockhost(cptr) ? cli_sockhost(cptr) : cli_sock_ip(cptr));

  if (!CapActive(cptr, CAP_SASL))
    return 0;

  if (parc < 2) 
    return need_more_params(cptr, "AUTHENTICATE");

  if (strlen(parv[1]) > 400)
    return send_reply(cptr, ERR_SASLTOOLONG);

  if (IsSASLComplete(cptr))
    return send_reply(cptr, ERR_SASLALREADY);


  if (!(acptr = cli_saslagent(cptr))) {
    if (strcmp(feature_str(FEAT_SASL_SERVER), "*"))
      acptr = find_match_server((char *)feature_str(FEAT_SASL_SERVER));
    else
      acptr = NULL;
  }

  if (!acptr && strcmp(feature_str(FEAT_SASL_SERVER), "*"))
    return send_reply(cptr, ERR_SASLFAIL, ": service unavailable");


  if (acptr && IsMe(acptr))
    return 0;


  if (!cli_saslcookie(cptr)) {
    do {
      cli_saslcookie(cptr) = ircrandom() & 0x7fffffff;
    } while (!cli_saslcookie(cptr));
    first = 1;
  }

  if (strchr(hoststr, ':') != NULL)
    ircd_snprintf(0, realhost, sizeof(realhost), "[%s]", hoststr);
  else
    ircd_strncpy(realhost, hoststr, sizeof(realhost));

  if (acptr) {
    if (first) {
      if (!EmptyString(cli_sslclifp(cptr)))
        sendcmdto_one(&me, CMD_SASL, acptr, "%C %C!%u.%u S %s :%s", acptr, &me,
                      cli_fd(cptr), cli_saslcookie(cptr),
                      parv[1], cli_sslclifp(cptr));
      else
        sendcmdto_one(&me, CMD_SASL, acptr, "%C %C!%u.%u S :%s", acptr, &me,
                      cli_fd(cptr), cli_saslcookie(cptr), parv[1]);
      if (feature_bool(FEAT_SASL_SENDHOST))
        sendcmdto_one(&me, CMD_SASL, acptr, "%C %C!%u.%u H :%s@%s:%s", acptr, &me,
                      cli_fd(cptr), cli_saslcookie(cptr), cli_username(cptr),
                      realhost, cli_sock_ip(cptr));
    } else {
      sendcmdto_one(&me, CMD_SASL, acptr, "%C %C!%u.%u C :%s", acptr, &me,
                    cli_fd(cptr), cli_saslcookie(cptr), parv[1]);
    }
  } else {
    if (first) {
      if (!EmptyString(cli_sslclifp(cptr)))
        sendcmdto_serv_butone(&me, CMD_SASL, cptr, "* %C!%u.%u S %s :%s", &me,
                              cli_fd(cptr), cli_saslcookie(cptr),
                              parv[1], cli_sslclifp(cptr));
      else
        sendcmdto_serv_butone(&me, CMD_SASL, cptr, "* %C!%u.%u S :%s", &me,
                              cli_fd(cptr), cli_saslcookie(cptr), parv[1]);
      if (feature_bool(FEAT_SASL_SENDHOST))
        sendcmdto_serv_butone(&me, CMD_SASL, cptr, "* %C!%u.%u H :%s@%s:%s", &me,
                              cli_fd(cptr), cli_saslcookie(cptr), cli_username(cptr),
                              realhost, cli_sock_ip(cptr));
    } else {
      sendcmdto_serv_butone(&me, CMD_SASL, cptr, "* %C!%u.%u C :%s", &me,
                            cli_fd(cptr), cli_saslcookie(cptr), parv[1]);
    }
  }

  if (!t_active(&cli_sasltimeout(cptr)))
    timer_add(timer_init(&cli_sasltimeout(cptr)), sasl_timeout_callback, (void*) cptr,
              TT_RELATIVE, feature_int(FEAT_SASL_TIMEOUT));

  return 0;
}

