	return -1;
}

char *url_decode_r(char *to, char *url, size_t size) {
    char *s = url,           
         *d = to,            
         *e = &to[size - 1]; 

    while(*s && d < e) {
        if(unlikely(*s == '%')) {
            if(likely(s[1] && s[2])) {
                *d++ = from_hex(s[1]) << 4 | from_hex(s[2]);
                s += 2;
            }
        }
        else if(unlikely(*s == '+'))
            *d++ = ' ';

        else
            *d++ = *s;

        s++;
    }

    *d = '\0';

    return to;
}

char *url_decode_r(char *to, char *url, size_t size) {
