        if (1 + 1 + len > ber_int_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        *data = &ber_int[2];
        *data_len = len;
        if (len > 0 && ber_int[2] == 0x00) {
            *data = &ber_int[3];
            *data_len = len - 1;
        }
        *field_len = 1 + 1 + len;
        return CKR_OK;
    }

    length_octets = ber_int[1] & 0x7F;
    if (1 + 1 + length_octets > ber_int_len) {
        TRACE_ERROR("BER length is larger than encoded data.\n");
        return CKR_FUNCTION_FAILED;
    }

    if (length_octets == 1) {
        len = ber_int[2];
        if (1 + (1 + 1) + len > ber_int_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        *data = &ber_int[3];
        *data_len = len;
        if (len > 0 && ber_int[3] == 0x00) {
            *data = &ber_int[4];
            *data_len = len - 1;
        }
        *field_len = 1 + (1 + 1) + len;
        return CKR_OK;
    }

    if (length_octets == 2) {
        len = ber_int[2];
        len = len << 8;
        len |= ber_int[3];
        if (1 + (1 + 2) + len > ber_int_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        *data = &ber_int[4];
        *data_len = len;
        if (len > 0 && ber_int[4] == 0x00) {
            *data = &ber_int[5];
            *data_len = len - 1;
        }
        *field_len = 1 + (1 + 2) + len;
        return CKR_OK;
    }

    if (length_octets == 3) {
        len = ber_int[2];
        len = len << 8;
        len |= ber_int[3];
        len = len << 8;
        len |= ber_int[4];
        if (1 + (1 + 3) + len > ber_int_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        *data = &ber_int[5];
        *data_len = len;
        if (len > 0 && ber_int[5] == 0x00) {
            *data = &ber_int[6];
            *data_len = len - 1;
        }
        *field_len = 1 + (1 + 3) + len;
        return CKR_OK;
    }



    TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));

    return CKR_FUNCTION_FAILED;
}

