    if (rc != CKR_OK || field_len > data_len) {
        TRACE_ERROR("%s ber_decode_OCTET_STRING (SKI) failed\n", __func__);
        return CKR_FUNCTION_FAILED;
    }

    data += field_len;
    data_len -= field_len;

    rc = ber_decode_OCTET_STRING(data, data_len, &spki, &spki_len, &field_len);
    if (rc != CKR_OK || field_len > data_len) {
        TRACE_ERROR("%s ber_decode_OCTET_STRING (SPKI) failed\n", __func__);
        return CKR_FUNCTION_FAILED;
    }

    data += field_len;
    data_len -= field_len;

    rc = ber_decode_OCTET_STRING(data, data_len, &cnt, &cnt_len, &field_len);
    if (rc != CKR_OK || field_len > data_len) {
        TRACE_ERROR("%s ber_decode_OCTET_STRING (COUNTER) failed\n", __func__);
        return CKR_FUNCTION_FAILED;
    }

#ifdef DEBUG
        TRACE_DEBUG("SKI (size: %lu):\n", ski_field_len);
        TRACE_DEBUG_DUMP("    ", ski_field, ski_field_len);
        TRACE_DEBUG("SPKI (size: %lu):\n", spki_len);
        TRACE_DEBUG_DUMP("    ", spki, spki_len);
        TRACE_DEBUG("TCounter (size: %lu):\n", cnt_len);
        TRACE_DEBUG_DUMP("    ", cnt, cnt_len);
#endif

    if (ski_field_len != XCP_CERTHASH_BYTES) {
        TRACE_ERROR("%s SKI length is not as expected (%lu != %u)\n", __func__,
                    ski_field_len, XCP_CERTHASH_BYTES);
        return CKR_BUFFER_TOO_SMALL;
    }
    memcpy(ski, ski_field, ski_field_len);

    if (cnt_len > XCP_ADMCTR_BYTES) {
        TRACE_ERROR("%s counter length is too large (%lu > %lu)\n", __func__,
                    cnt_len, XCP_ADMCTR_BYTES);
        return CKR_FUNCTION_FAILED;
    }
    memset(tcounter, 0, XCP_ADMCTR_BYTES - cnt_len);
    memcpy(tcounter + XCP_ADMCTR_BYTES - cnt_len, cnt, cnt_len);

    p = (const unsigned char *)spki;
    *ec_pubkey = d2i_PUBKEY(NULL, &p, spki_len);
    if (*ec_pubkey == NULL) {
        TRACE_ERROR("%s d2i_PUBKEY failed\n", __func__);
        return CKR_FUNCTION_FAILED;
    }

    return rc;
}

static CK_RV ica_build_ec_pub_key(OBJECT *key_obj, ICA_EC_KEY **eckey,
                                  unsigned int *privlen)
{
    CK_RV ret = CKR_OK;
    CK_ATTRIBUTE *attr;
    unsigned char x_array[ICATOK_EC_MAX_D_LEN];
    unsigned char y_array[ICATOK_EC_MAX_D_LEN];
    int rc, nid;
    CK_BYTE *ecpoint;
    CK_ULONG ecpoint_len, field_len;


    ret = ica_prepare_ec_key(key_obj, eckey, privlen, &nid);
    if (ret != CKR_OK) {
        TRACE_ERROR("ica_prepare_ec_key() failed with rc = 0x%lx. \n", ret);
        return ret;
    }


    ret = template_attribute_get_non_empty(key_obj->template, CKA_EC_POINT,
                                           &attr);
    if (ret != CKR_OK) {
        TRACE_ERROR("%s\n", ock_err(ERR_TEMPLATE_INCOMPLETE));
        ret = CKR_TEMPLATE_INCOMPLETE;
        goto end;
    }


    ret = ber_decode_OCTET_STRING(attr->pValue, &ecpoint, &ecpoint_len,
                                  &field_len);
    if (ret != CKR_OK || field_len != attr->ulValueLen) {
        TRACE_DEVEL("ber_decode_OCTET_STRING failed\n");
        ret = CKR_ATTRIBUTE_VALUE_INVALID;
        goto end;
    }


    ret = set_pubkey_coordinates(nid, ecpoint, ecpoint_len,
                                 *privlen, x_array, y_array);
    if (ret != 0) {
        TRACE_ERROR("Cannot determine public key coordinates from "
                    "given public key\n");
        goto end;
    }


    rc = p_ica_ec_key_init(x_array, y_array, NULL, *eckey);
    if (rc != 0) {
        switch (rc) {
        case ENODEV:
            TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_NOT_SUPPORTED));
            ret = CKR_FUNCTION_NOT_SUPPORTED;
            break;
        case EPERM:
            TRACE_ERROR("ica_ec_key_init() failed with rc=EPERM, probably curve not supported by openssl.\n");
            ret = CKR_CURVE_NOT_SUPPORTED;
            break;
        default:
            TRACE_ERROR("ica_ec_key_init() failed with rc = %d \n", rc);
            ret = CKR_FUNCTION_FAILED;
            break;
        }
        goto end;
    }

end:
    if (ret != CKR_OK) {
        p_ica_ec_key_free(*eckey);
        *eckey = NULL;
    }

    return ret;
}

