    (void)DetectRun(tv, de_ctx, det_ctx, p);
}

void ShortenString(const char *input,
    char *output, size_t output_size, char c)
{
    const size_t str_len = strlen(input);
    size_t half = (output_size - 1) / 2;


    if (half * 2 == (output_size - 1)) {
        half = half - 1;
    }

    size_t spaces = (output_size - 1) - (half * 2);


    snprintf(output, half+1, "%s", input);


    size_t length = half;
    for (size_t i = half; i < half + spaces; i++) {
        char s[2] = "";
        snprintf(s, sizeof(s), "%c", c);
        length = strlcat(output, s, output_size);
    }

    snprintf(output + length, half + 1, "%s", input + (str_len - half));
}

void ShortenString(const char *input,
    char *output, size_t output_size, char c)
{
    if (output_size == 0)
        return;

    const size_t str_len = strlen(input);
    size_t half = (output_size - 1) / 2;


    if (half * 2 == (output_size - 1)) {
        half = half - 1;
    }
    DEBUG_VALIDATE_BUG_ON(half > output_size);
    if (half == 0 || half > output_size)
        return;

    size_t spaces = (output_size - 1) - (half * 2);


    snprintf(output, half+1, "%s", input);


    size_t length = half;
    for (size_t i = half; i < half + spaces; i++) {
        char s[2] = "";
        snprintf(s, sizeof(s), "%c", c);
        length = strlcat(output, s, output_size);
    }

    snprintf(output + length, half + 1, "%s", input + (str_len - half));
}

static bool TlsSubjectAltNameGetData(DetectEngineThreadCtx *det_ctx, const void *txv,
        const uint8_t flags, uint32_t idx, const uint8_t **buf, uint32_t *buf_len)
{
    const SSLState *ssl_state = (SSLState *)txv;
    const SSLStateConnp *connp;

    connp = &ssl_state->server_connp;

    if (idx >= connp->cert0_sans_len) {
        return false;
    }

    *buf = (const uint8_t *)connp->cert0_sans[idx];
    *buf_len = (uint32_t)strlen(connp->cert0_sans[idx]);
    return true;
}

